{
  "name": "opencode-lmstudio-warm",
  "version": "0.3.2",
  "description": "Deterministic LM Studio model pre-warm gate for opencode — loads and keeps the target model resident before every request, healing cold starts and mid-session TTL evictions.",
  "type": "module",
  "main": "./src/index.ts",
  "exports": {
    ".": {
      "types": "./src/index.ts",
      "import": "./src/index.ts"
    }
  },
  "files": [
    "src",
    "examples",
    "README.md",
    "LICENSE",
    "CHANGELOG.md"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "lmstudio",
    "lm-studio",
    "llm",
    "local-llm",
    "model-loading",
    "prewarm",
    "warm",
    "bun"
  ],
  "license": "MIT",
  "author": "Diego Marino <diego@petalo.xyz>",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/diegomarino/lm-studio-warm.git",
    "directory": "packages/opencode"
  },
  "homepage": "https://github.com/diegomarino/lm-studio-warm#readme",
  "bugs": {
    "url": "https://github.com/diegomarino/lm-studio-warm/issues"
  },
  "engines": {
    "bun": ">=1.0.0"
  },
  "scripts": {
    "typecheck": "tsc --noEmit -p tsconfig.json",
    "test": "bun test --timeout 30000",
    "e2e": "test/e2e/verify.sh",
    "check": "bun run typecheck && bun run test && if command -v shellcheck >/dev/null; then shellcheck --severity=warning test/e2e/verify.sh; else echo 'shellcheck not installed — lint of test/e2e/verify.sh skipped'; fi"
  },
  "dependencies": {
    "lm-studio-warm-core": "^0.2.2"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.17.10",
    "@types/bun": "^1.3.14",
    "@types/node": "^22.15.0",
    "typescript": "^5.8.3"
  }
}

{
  "$schema": "https://opencode.ai/config.json",
  "plugin": ["opencode-lm-studio-warm"],
  "model": "lmstudio/your-main-model-key",
  "small_model": "lmstudio/your-small-model-key",
  "provider": {
    "lmstudio": {
      "npm": "@ai-sdk/openai-compatible",
      "name": "LM Studio (local)",
      "options": {
        "baseURL": "http://127.0.0.1:1234/v1",
        "apiKey": "{env:LM_API_TOKEN}",
        "headerTimeout": 600000,
        "chunkTimeout": 120000
      },
      "models": {
        "your-main-model-key": { "name": "Your main local model" },
        "your-small-model-key": { "name": "Your small/title local model" }
      }
    }
  }
}
